const item = $input.first().json;
const text = [item.snippet, item.textPlain, item.textHtml].filter(Boolean).join('\n');
const lines = String(text).split(/\n+/).map(l => l.trim()).filter(Boolean).slice(0, 8);
return [{
  json: {
    project: item.subject?.match(/پروژه\s+\S+/)?.[0] || 'ثبت نشده',
    subject: item.subject || 'گزارش بدون عنوان',
    sender: item.from?.text || item.from || 'Gmail',
    facts: lines.length ? lines : ['متن ایمیل خالی بود؛ نیاز به بررسی دستی.'],
    confidence: 0,
    owner: 'مدیر پروژه',
    priority: /فوری|بحرانی|تأخیر/i.test(String(item.subject)) ? 'بحرانی' : 'مهم'
  }
}];
